#!/usr/bin/env node
// PreToolUse hook: block writes to generated files.
//
// Triggered before any Edit / Write tool call. Reads the tool input from
// stdin, checks the target path against a blocklist of files that should
// never be edited by hand (because they're regenerated by codegen), and
// blocks with exit code 2 if matched.
//
// Why this exists:
//   schema.gql is overwritten by `pnpm gql` on every codegen run.
//   libs/**/.generated/ is the same. Manual edits are silently lost.
//   The AGENTS.md rule says "NEVER edit schema.gql" — this hook makes
//   the rule deterministic instead of relying on Agent compliance.

const BLOCKED_PATTERNS = [
  /\bschema\.gql$/,
  /\/\.generated\//,
  /\.generated\.(ts|js|json)$/,
];

let raw = '';
process.stdin.on('data', (chunk) => { raw += chunk; });
process.stdin.on('end', () => {
  let input;
  try { input = JSON.parse(raw); } catch { process.exit(0); }

  const filePath =
    input?.tool_input?.file_path ??
    input?.tool_input?.path ??
    '';

  if (!filePath) process.exit(0);

  for (const pattern of BLOCKED_PATTERNS) {
    if (pattern.test(filePath)) {
      process.stderr.write(
        `🛑 BLOCKED: ${filePath} is a generated file.\n\n` +
        `This file is overwritten by codegen on every run. Manual edits\n` +
        `will be silently lost. If you need to change what it contains,\n` +
        `edit the SOURCE that codegen reads from instead (e.g. .graphql\n` +
        `operations, entity definitions).\n`
      );
      process.exit(2);
    }
  }
  process.exit(0);
});
